seq = ""

print(f"Scanning Sequence Length: {len(seq)}")
print("-" * 30)
print("DEAMIDATION HOTSPOTS (NG, NS):")
for i in range(len(seq)-1):
    if seq[i:i+2] in ['NG', 'NS']:
        print(f"Found {seq[i:i+2]} at position {i+1}")

print("-" * 30)
print("OXIDATION HOTSPOTS (M, W):")
for i in range(len(seq)):
    if seq[i] in ['M', 'W']:
        print(f"Found {seq[i]} at position {i+1}")
